/**
 * GOLDEN EVALUATION CORPUS for the dictionary sentiment gauge — 500 real
 * headlines sampled (seeded, stratified by day / lane / finance-vs-politics
 * bucket) from the published story ledger (stories.json, 2026-10-16 →
 * 2026-11-14). Hand-labeled by careful reading under fixed rules:
 *
 *   positive — clear bullish news for the subject market/asset/company
 *              (gains, beats, records, approvals, inflows, easing, recovery)
 *   negative — clear bearish news (losses, declines, crashes, defaults,
 *              probes, sanctions, layoffs, tightening, outflows)
 *   neutral  — no directional valence, purely factual, ambiguous, or
 *              balanced bullish+bearish signals
 *
 * This file is evaluation data only: it is imported by the eval script and
 * the regression test, never by the runtime pipeline. Do not hand-edit
 * labels without re-running the two-pass consistency check described in
 * internal/sentiment-lexicon-v2.md.
 */

/** A single hand-labeled headline. `bucket` is finance/politics sampling stratum. */
export interface GoldenHeadline {
  title: string;
  label: "positive" | "negative" | "neutral";
  lane: "zh" | "external";
  bucket: "fin" | "pol";
  edition: string;
}

